function readRawProjectConfig(projectRoot) {
    try {
        const file = join(projectRoot, ".flisk", PROJECT_JSON);
        if (!existsSync(file))
            return null;
        return JSON.parse(readFileSync(file, "utf-8"));
    }
    catch {
        return null;
    }
}
function projectEnvLookup(projectRoot, env = process.env) {
    const merged = {};
    const envFile = env[PROJECT_ENV_FILE_VAR] || join(projectRoot, ".env");
    try {
        if (existsSync(envFile)) {
            for (const [key, value] of parseEnv(readFileSync(envFile, "utf-8"))) {
                merged[key] = value;
            }
        }
    }
    catch {
        // Ignore unreadable .env; other checks report it.
    }
    for (const [key, value] of Object.entries(env)) {
        if (value !== undefined)
            merged[key] = value;
    }
    return merged;
}
/**
 * Return every existing project Compose file that `flisk up` loads (platform infra compose files
 * plus any user-authored stack compose files). Paths are absolute.
 */
export function discoverProjectComposeFiles(projectRoot, resources, options, env = process.env) {
    const files = [];
    const addIfExists = (absPath) => {
        if (existsSync(absPath) && !files.includes(absPath))
            files.push(absPath);
    };
    const rawConfig = readRawProjectConfig(projectRoot);
    const optional = rawConfig?.optional_infra;
    const dbEnabled = isDatabaseCapabilityEnabled(projectRoot, options);
    const gatewayEnabled = isGatewayEnabled(projectRoot, options);
    if (dbEnabled) {
        addIfExists(join(projectRoot, "services", "platform", "database-management", DOCKER_COMPOSE_FILE));
        addIfExists(join(projectRoot, "services", "platform", "messaging", DOCKER_COMPOSE_FILE));
    }
    if (optional?.verdaccio === true) {
        addIfExists(join(projectRoot, "docker-compose.verdaccio.yml"));
    }
    const lookup = projectEnvLookup(projectRoot, env);
    const infisicalOn = (lookup.INFISICAL_ENABLED ?? "").toLowerCase() === "true" ||
        rawConfig?.always_enabled_infra?.includes("infisical") === true;
    if (infisicalOn) {
        addIfExists(join(projectRoot, "docker-compose.infisical.yml"));
    }
    if (gatewayEnabled) {
        const proxyFiles = PLATFORM_PROXY_COMPOSE_FILES.map((rel) => join(projectRoot, rel));
        if (proxyFiles.every((file) => existsSync(file))) {
            for (const file of proxyFiles)
                addIfExists(file);
        }
        else {
            addIfExists(join(projectRoot, ".flisk", ".flisk-out", "docker-compose.traefik.yml"));
        }
    }
    if (optional?.monitoring === true) {
        addIfExists(join(projectRoot, "services", "platform", "monitoring", DOCKER_COMPOSE_FILE));
    }
    if (optional?.debezium === true) {
        addIfExists(join(projectRoot, "services", "platform", "cdc", "docker-compose.enhanced.yml"));
    }
    if (optional?.elk === true) {
        addIfExists(join(projectRoot, "docker", "elk-compose.yml"));
    }
    const discovered = resources ?? discoverResourcesFromRoot(projectRoot);
    const seenDirs = new Set();
    for (const resource of discovered) {
        for (const dir of [resource.path, dirname(resource.path)]) {
            if (seenDirs.has(dir))
                continue;
            seenDirs.add(dir);
            const rel = relative(projectRoot, dir).split(sep).join("/");
            if (!rel || rel.startsWith("..") || rel.includes(AUTOGENERATED_DIR))
                continue;
            for (const filename of [DOCKER_COMPOSE_FILE, "docker-compose.yaml"]) {
                addIfExists(join(dir, filename));
            }
        }
    }
    return files;
}
function vendoredExtensionSupportsExternalScan(projectRoot) {
    const infraLoader = join(projectRoot, ".flisk", ".flisk-out", "flisk-cli-ext", "engine", "topologies", "tilt", "resources", "infra-loader.star");
    if (!existsSync(infraLoader))
        return true;
    try {
        return readFileSync(infraLoader, "utf-8").includes("external_compose_networks");
    }
    catch {
        return true;
    }
}
/**
 * Scan every Compose file that `flisk up` loads and classify its declared external networks into:
 * - `managed`: `<project>_*` networks that `init-networks` will create automatically
 * - `unmanaged`: non-`<project>_*` networks (or unresolved interpolations) that `init-networks` will not create
 * - `staleManaged`: extra `<project>_*` networks that a stale vendored extension will not create yet
 */
export function scanProjectExternalNetworks(projectRoot, resources, env = process.env, options) {
    const name = (readProjectNameOrUndefined(projectRoot) ?? "flisk-project").toLowerCase();
    const projectPrefix = `${toComposeProjectName(name)}_`;
    const lookup = projectEnvLookup(projectRoot, env);
    const rawConfig = readRawProjectConfig(projectRoot);
    const fixedPlatformNetworks = new Set([
        `${projectPrefix}traefik-public`,
        `${projectPrefix}backend`,
        `${projectPrefix}database`,
    ]);
    if ((lookup.INFISICAL_ENABLED ?? "").toLowerCase() === "true" ||
        rawConfig?.always_enabled_infra?.includes("infisical") === true) {
        fixedPlatformNetworks.add(`${projectPrefix}infisical-network`);
    }
    if (rawConfig?.optional_infra?.verdaccio === true) {
        fixedPlatformNetworks.add(`${projectPrefix}verdaccio-network`);
    }
    const vendoredScans = vendoredExtensionSupportsExternalScan(projectRoot);
    const managed = [];
    const unmanaged = [];
    const staleManaged = [];
    const seenKeys = new Set();
    for (const absFile of discoverProjectComposeFiles(projectRoot, resources, options, env)) {
        let content;
        try {
            content = readFileSync(absFile, "utf-8");
        }
        catch {
            continue;
        }
        const relFile = relative(projectRoot, absFile).split(sep).join("/") || absFile;
        for (const entry of parseExternalComposeNetworks(content, lookup)) {
            const dedupeKey = `${relFile}\0${entry.rawName}`;
            if (seenKeys.has(dedupeKey))
                continue;
            seenKeys.add(dedupeKey);
            const record = { ...entry, file: relFile };
            if (entry.unresolvedVars.length > 0 ||
                !entry.name.startsWith(projectPrefix) ||
                entry.name.length <= projectPrefix.length ||
                !isSafeDockerNetworkName(entry.name)) {
                unmanaged.push(record);
            }
            else if (!vendoredScans && !fixedPlatformNetworks.has(entry.name)) {
                staleManaged.push(record);
            }
            else {
                managed.push(record);
            }
        }
    }
    return { projectPrefix, managed, unmanaged, staleManaged, fixedPlatformNetworks };
}
/**
 * Warnings for `flisk config verify` naming external Compose networks that `init-networks` will not
 * create (non-`<project>_*` names, unresolved variables, or a stale vendored extension).
 */
export function externalNetworkWarnings(projectRoot, resources, env = process.env) {
    const scan = scanProjectExternalNetworks(projectRoot, resources, env);
    const warnings = [];
    for (const entry of scan.unmanaged) {
        if (entry.unresolvedVars.length > 0) {
            warnings.push(`${entry.file} declares external network "${entry.rawName}", whose variable (${entry.unresolvedVars.join(", ")}) is unset; init-networks will not create it`);
        }
        else {
            warnings.push(`${entry.file} declares external network "${entry.name}", which init-networks does not create (only "${scan.projectPrefix}*" networks are created automatically); ensure it exists in Docker or rename it to "${scan.projectPrefix}<name>"`);
        }
    }
    for (const entry of scan.staleManaged) {
        warnings.push(`${entry.file} declares external network "${entry.name}", which the vendored extension in .flisk/.flisk-out/flisk-cli-ext will not create; run \`flisk config regenerate\` so init-networks creates it`);
    }
    return warnings;
}
function defaultListDockerNetworks() {
    const dockerPath = findOnPath("docker");
    if (!dockerPath)
        return null;
    try {
        const output = execFileSync(dockerPath, ["network", "ls", "--format", "{{.Name}}"], {
            encoding: "utf-8",
            timeout: 8000,
            stdio: ["ignore", "pipe", "ignore"],
            windowsHide: true,
        });
        return output
            .split(/\r?\n/)
            .map((line) => line.trim())
            .filter(Boolean);
    }
    catch {
        return null;
    }
}
/**
 * Doctor check for external Docker networks declared by project Compose files.
 * Networks prefixed with `<project>_` are created automatically by `init-networks` (provided the
 * vendored extension is up to date). Any other external network must already exist in Docker or
 * `flisk up` will fail after minutes with "network <name> declared as external, but could not be found".
 */
export function checkExternalComposeNetworks(projectRoot = findProjectRoot() ?? process.cwd(), resources, listDockerNetworks = defaultListDockerNetworks, env = process.env, options) {
    const scan = scanProjectExternalNetworks(projectRoot, resources, env, options);
    const extraManaged = scan.managed.filter((entry) => !scan.fixedPlatformNetworks.has(entry.name));
    if (extraManaged.length === 0 && scan.unmanaged.length === 0 && scan.staleManaged.length === 0) {
        return {
            name: "External compose networks",
            didPass: true,
            isSkipped: true,
            message: "No project compose file declares extra external networks",
        };
    }
    if (scan.unmanaged.length === 0 && scan.staleManaged.length === 0) {
        const names = [...new Set(extraManaged.map((entry) => entry.name))].sort((a, b) => a.localeCompare(b));
        return {
            name: "External compose networks",
            didPass: true,
            message: `Declared external networks (${names.join(", ")}) will be created by init-networks`,
        };
    }
    const dockerNetworks = listDockerNetworks();
    if (dockerNetworks === null) {
        const names = [
            ...new Set([
                ...scan.unmanaged.map((entry) => entry.name || entry.rawName),
                ...scan.staleManaged.map((entry) => entry.name),
            ]),
        ].sort((a, b) => a.localeCompare(b));
        return {
            name: "External compose networks",
            didPass: false,
            isWarning: true,
            message: `Docker did not answer; could not verify external networks (${names.join(", ")}) that init-networks will not create`,
            fix: "Start Docker and re-run `flisk doctor`, or run `flisk config regenerate` if the vendored extension is stale",
        };
    }
    const existing = new Set(dockerNetworks);
    const missingUnmanaged = scan.unmanaged.filter((entry) => entry.unresolvedVars.length > 0 || !existing.has(entry.name));
    const missingStale = scan.staleManaged.filter((entry) => !existing.has(entry.name));
    if (missingUnmanaged.length === 0 && missingStale.length === 0) {
        return {
            name: "External compose networks",
            didPass: true,
            message: "All declared external networks exist in Docker or will be created by init-networks",
        };
    }
    const lines = [];
    for (const entry of missingUnmanaged) {
        if (entry.unresolvedVars.length > 0) {
            lines.push(`${entry.file}: external network "${entry.rawName}" has unset variable(s) ${entry.unresolvedVars.join(", ")}`);
        }
        else {
            lines.push(`${entry.file}: external network "${entry.name}" not found in Docker (init-networks only creates "${scan.projectPrefix}*" networks)`);
        }
    }
    for (const entry of missingStale) {
        lines.push(`${entry.file}: external network "${entry.name}" not found in Docker (vendored extension is older and does not scan external compose networks)`);
    }
    const fixes = [];
    if (missingStale.length > 0) {
        fixes.push("Run `flisk config regenerate` so init-networks creates the project external networks");
    }
    const creatable = missingUnmanaged.filter((entry) => entry.unresolvedVars.length === 0 && isSafeDockerNetworkName(entry.name));
    if (creatable.length > 0) {
        const createCmds = [...new Set(creatable.map((entry) => entry.name))]
            .map((name) => `docker network create ${name}`)
            .join(" && ");
        fixes.push(`Create the missing network(s) with \`${createCmds}\`, or rename them with the "${scan.projectPrefix}" prefix so init-networks creates them`);
    }
    if (missingUnmanaged.some((entry) => entry.unresolvedVars.length > 0)) {
        fixes.push("Set the missing environment variable(s) in .env or the shell");
    }
    return {
        name: "External compose networks",
        didPass: false,
        message: `${formatCount(lines.length, "missing external Docker network")}:\n    ${lines.join("\n    ")}`,
        fix: fixes.join(". "),
    };
}
